CREATE OR REPLACE FUNCTION public.convert_referral(_referral_code text, _converted_user_id uuid, _listing_id uuid DEFAULT NULL::uuid, _amount numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _ref_id uuid;
  _commission_id uuid;
BEGIN
  SELECT id INTO _ref_id FROM public.referrals WHERE code = _referral_code LIMIT 1;
  IF _ref_id IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.commissions (referral_id, converted_user_id, listing_id, amount, status)
  VALUES (_ref_id, _converted_user_id, _listing_id, _amount, 'pending')
  RETURNING id INTO _commission_id;

  UPDATE public.referrals SET conversions = conversions + 1 WHERE id = _ref_id;
  RETURN _commission_id;
END $function$

CREATE OR REPLACE FUNCTION public.convert_referral(_referral_id uuid, _amount numeric, _currency text DEFAULT 'USD'::text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referral public.referrals%ROWTYPE;
  v_company_id uuid;
  v_owner uuid;
  v_commission_id uuid;
BEGIN
  SELECT * INTO v_referral FROM public.referrals WHERE id = _referral_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Referral not found'; END IF;

  SELECT company_id INTO v_company_id FROM public.listings WHERE id = v_referral.listing_id;
  IF v_company_id IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;

  SELECT owner_id INTO v_owner FROM public.companies WHERE id = v_company_id;
  IF v_owner IS NULL OR v_owner <> auth.uid() THEN
    IF NOT public.has_role(auth.uid(), 'admin') THEN
      RAISE EXCEPTION 'Only the listing company owner can record a conversion';
    END IF;
  END IF;

  UPDATE public.referrals SET conversions = conversions + 1 WHERE id = _referral_id;

  INSERT INTO public.commissions (agent_id, company_id, listing_id, amount, currency, status, notes)
  VALUES (v_referral.agent_id, v_company_id, v_referral.listing_id, _amount, COALESCE(_currency,'USD'), 'pending', _notes)
  RETURNING id INTO v_commission_id;

  RETURN v_commission_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_listing_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  canonical_owner uuid;
BEGIN
  SELECT company.owner_id
  INTO canonical_owner
  FROM public.companies AS company
  WHERE company.id = NEW.company_id;

  IF canonical_owner IS NULL THEN
    RAISE EXCEPTION 'listing_company_owner_not_found';
  END IF;

  NEW.owner_id := canonical_owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stamp_commission_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM 'paid') THEN
    NEW.paid_at = now();
  END IF;
  RETURN NEW;
END;
$function$
